(function(root){'use strict';const A=root.AIBrain=root.AIBrain||{};A.selectMemory=function(request,memories=[],opts={}){const q=new Set(A.tokens(request)),limit=opts.limit||12;return memories.map(m=>{const text=A.tokens([m.title,m.summary,m.content,...(m.tags||[])].filter(Boolean).join(' '));let score=0;for(const t of text)if(q.has(t))score++;if(m.projectId&&opts.projectId===m.projectId)score+=5;if(m.pinned)score+=3;return{memory:m,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,limit).map(x=>x.memory);};})(typeof globalThis!=='undefined'?globalThis:this);
